const handleRecordManualPayment = Effect.fn('Finance.handleRecordManualPayment')(function* recordManualPayment(
  command: CommandOf<'RecordManualPayment'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  const previous = yield* findInvoice(context.state, command.invoiceRef, context.scope);
  if (previous.businessState !== 'CONFIRMED') {
    return yield* conflict('payment_requires_confirmed_invoice');
  }
  const paidMinor = previous.paidMinor + command.amountMinor;
  if (paidMinor > previous.totalMinor) {
    return yield* rejected('payment_exceeds_remaining_amount');
  }
  const invoice: Invoice = {
    ...previous,
    paidMinor,
    paymentState: derivePaymentState(paidMinor, previous.totalMinor),
    updatedAt: context.input.now,
  };
  const changed = replace(context.state, invoice);
  return {
    ...changed,
    state: {
      ...changed.state,
      manualPayments: [
        ...(context.state.manualPayments ?? []),
        {
          ...actorOf(context, command.actorLabel),
          amountMinor: command.amountMinor,
          id: context.input.attemptId,
          invoiceResourceId: previous.ref.resourceId,
          ...(command.note === undefined ? {} : { note: command.note }),
          paidOn: command.paidOn,
          recordedAt: context.input.now,
        },
      ],
    },
  };
});

const handleRecordReminder = Effect.fn('Finance.handleRecordReminder')(function* recordReminder(
  command: CommandOf<'RecordReminder'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  const invoice = yield* findInvoice(context.state, command.invoiceRef, context.scope);
  if (invoice.businessState !== 'CONFIRMED' || invoice.paidMinor >= invoice.totalMinor) {
    return yield* conflict('reminder_requires_open_invoice');
  }
  return stateOnly(
    {
      ...context.state,
      reminders: [
        ...(context.state.reminders ?? []),
        {
          ...actorOf(context, command.actorLabel),
          createdAt: context.input.now,
          deliveryMode: 'SIMULATED',
          id: context.input.attemptId,
          invoiceResourceId: invoice.ref.resourceId,
          recipient: command.recipient,
          status: 'SIMULATED_SENT',
          text: command.text,
        },
      ],
    },
    invoice,
  );
});

const handleCreateRecurringTemplate = Effect.fn('Finance.handleCreateRecurringTemplate')(function* createTemplate(
  command: CommandOf<'CreateRecurringTemplate'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  const { _tag: _command, ...fields } = command;
  if (computeInvoiceTotals(command.lines)?.totalMinor === undefined) {
    return yield* rejected('invoice_amount_out_of_range');
  }
  return stateOnly({
    ...context.state,
    recurringTemplates: [
      ...(context.state.recurringTemplates ?? []),
      { ...fields, active: true, createdAt: context.input.now, id: context.input.resourceId },
    ],
  });
});

const handleSetRecurringTemplateActive = Effect.fn('Finance.handleSetRecurringTemplateActive')(function* setActive(
  command: CommandOf<'SetRecurringTemplateActive'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  const templates = context.state.recurringTemplates ?? [];
  if (!templates.some((template) => template.id === command.templateId)) {
    return yield* new FinanceNotFound({ code: 'finance_not_found', reason: 'Recurring template not found' });
  }
  return stateOnly({
    ...context.state,
    recurringTemplates: templates.map((template) =>
      template.id === command.templateId ? { ...template, active: command.active } : template,
    ),
  });
});

const handleGenerateRecurringInvoice = Effect.fn('Finance.handleGenerateRecurringInvoice')(function* generate(
  command: CommandOf<'GenerateRecurringInvoice'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  const { input, scope, state, validators } = context;
  const template = (state.recurringTemplates ?? []).find((entry) => entry.id === command.templateId);
  if (template === undefined) {
    return yield* new FinanceNotFound({ code: 'finance_not_found', reason: 'Recurring template not found' });
  }
  if (!template.active) {
    return yield* conflict('recurring_template_inactive');
  }
  const duplicate = state.invoices.some(
    (invoice) =>
      invoice.recurringTemplateId === template.id &&
      invoice.recurringPeriod === command.period &&
      invoice.businessState !== 'VOIDED',
  );
  if (duplicate && !command.confirmDuplicate) {
    return yield* conflict('recurring_period_already_generated');
  }
  const totals = yield* draftTotals({ lines: template.lines });
  const issueDate = recurringIssueDate(command.period, template.issueDay);
  const number = nextInvoiceNumber(state.invoices);
  const invoice: Invoice = {
    ...totals,
    accountingCorrelation: `demo-accounting:${input.resourceId}`,
    accountingSyncState: 'NOT_SYNCED',
    budgetCategory: 'Nájemné',
    businessState: 'DRAFT',
    ...(template.contractRef === undefined ? {} : { contractRef: template.contractRef }),
    ...(template.counterpartyName === undefined ? {} : { counterpartyName: template.counterpartyName }),
    counterpartyRef: template.counterpartyRef,
    createdAt: input.now,
    currency: 'CZK',
    direction: 'OUTGOING',
    documentKind: 'RECURRING',
    documentNumber: number,
    dueDate: addCalendarDaysTo(issueDate, template.dueDays),
    issueDate,
    note: `Opakovaná faktura „${template.name}“ za období ${command.period}`,
    number,
    paidMinor: 0,
    ...(template.partyId === undefined ? {} : { partyId: template.partyId }),
    paymentState: 'UNPAID',
    ...(template.propertyRef === undefined ? {} : { propertyRef: template.propertyRef }),
    recurringPeriod: command.period,
    recurringTemplateId: template.id,
    ref: invoiceRefFor(scope, input.resourceId),
    ...(template.unitRef === undefined ? {} : { unitRef: template.unitRef }),
    updatedAt: input.now,
  };
  yield* validate(invoice, scope, validators);
  return { changed: true, invoice, state: { ...state, invoices: [...state.invoices, invoice] } };
});

const handleUpdateAccountingSetup = Effect.fn('Finance.handleUpdateAccountingSetup')(function* updateSetup(
  command: CommandOf<'UpdateAccountingSetup'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  const { _tag: _command, actorLabel, ...fields } = command;
  return stateOnly({
    ...context.state,
    accountingSetup: {
      ...fields,
      updatedAt: context.input.now,
      ...(actorLabel === undefined ? {} : { updatedByLabel: actorLabel }),
    },
  });
});

const handleCreateAccountingExport = Effect.fn('Finance.handleCreateAccountingExport')(function* createExport(
  command: CommandOf<'CreateAccountingExport'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  const { input, state } = context;
  const ids = [...new Set(command.invoiceResourceIds)];
  const selected = ids.map((id) => state.invoices.find((invoice) => invoice.ref.resourceId === id));
  if (selected.some((invoice) => invoice === undefined || invoice.businessState !== 'CONFIRMED')) {
    return yield* rejected('export_requires_confirmed_invoices');
  }
  const exports = state.accountingExports ?? [];
  const version = exports.length + 1;
  const batchNumber = `UP-${DateTime.formatIsoDateUtc(input.now).slice(0, 4)}-${String(version).padStart(3, '0')}`;
  const createdBy = command.actorLabel ?? input.principalId ?? 'neznámý uživatel';
  const documentsByInvoice = new Map((state.documents ?? []).map((document) => [document.invoiceResourceId, document]));
  const content = buildAccountingExport(
    command.format,
    selected.flatMap((invoice) =>
      invoice === undefined
        ? []
        : [
            {
              counterpartyName: invoice.counterpartyName ?? invoice.counterpartyRef.resourceId,
              documentLink:
                documentsByInvoice.get(invoice.ref.resourceId) === undefined
                  ? ''
                  : `ontos://siampark-billing-finance/documents/${documentsByInvoice.get(invoice.ref.resourceId)?.id}`,
              invoice,
            },
          ],
    ),
    { batchNumber, createdAt: DateTime.formatIso(input.now), createdBy, version },
  );
  return stateOnly({
    ...state,
    accountingExports: [
      ...exports,
      {
        ...actorOf(context, command.actorLabel),
        batchNumber,
        content,
        createdAt: input.now,
        fileName: exportFileName(command.format, { batchNumber, version }),
        format: command.format,
        id: input.resourceId,
        invoiceResourceIds: ids,
        schemaVersion: 'ontos-finance-export/1',
        sha256: createHash('sha256').update(content, 'utf8').digest('hex'),
        status: 'HANDED_OVER',
        version,
      },
    ],
  });
});

const handleConfirmAccountingExport = Effect.fn('Finance.handleConfirmAccountingExport')(function* confirmExport(
  command: CommandOf<'ConfirmAccountingExport'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  const exports = context.state.accountingExports ?? [];
  const target = exports.find((entry) => entry.id === command.exportId);
  if (target === undefined) {
    return yield* new FinanceNotFound({ code: 'finance_not_found', reason: 'Export not found' });
  }
  if (target.status !== 'HANDED_OVER') {
    return yield* conflict('export_already_confirmed');
  }
  return stateOnly({
    ...context.state,
    accountingExports: exports.map((entry) =>
      entry.id === command.exportId
        ? {
            ...entry,
            confirmationEvidence: command.evidence,
            confirmedAt: context.input.now,
            ...(command.actorLabel === undefined ? {} : { confirmedByLabel: command.actorLabel }),
            status: 'CONFIRMED_BY_ACCOUNTANT' as const,
          }
        : entry,
    ),
  });
});

const handleUpsertBudgetLine = Effect.fn('Finance.handleUpsertBudgetLine')(function* upsertBudget(
  command: CommandOf<'UpsertBudgetLine'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  const budgets = context.state.budgets ?? [];
  const id = command.id ?? context.input.resourceId;
  const clash = budgets.find(
    (entry) =>
      entry.id !== id &&
      entry.period === command.period &&
      entry.kind === command.kind &&
      entry.category.toLocaleLowerCase('cs') === command.category.toLocaleLowerCase('cs'),
  );
  if (clash !== undefined) {
    return yield* conflict('budget_line_already_exists');
  }
  if (command.id !== undefined && !budgets.some((entry) => entry.id === command.id)) {
    return yield* new FinanceNotFound({ code: 'finance_not_found', reason: 'Budget line not found' });
  }
  const { _tag: _command, actorLabel, id: _id, ...fields } = command;
  const line = { ...actorOf(context, actorLabel), ...fields, id, updatedAt: context.input.now };
  return stateOnly({
    ...context.state,
    budgets: command.id === undefined ? [...budgets, line] : budgets.map((entry) => (entry.id === id ? line : entry)),
  });
});

const handleDeleteBudgetLine = Effect.fn('Finance.handleDeleteBudgetLine')(function* deleteBudget(
  command: CommandOf<'DeleteBudgetLine'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  const budgets = context.state.budgets ?? [];
  if (!budgets.some((entry) => entry.id === command.id)) {
    return yield* new FinanceNotFound({ code: 'finance_not_found', reason: 'Budget line not found' });
  }
  return stateOnly({ ...context.state, budgets: budgets.filter((entry) => entry.id !== command.id) });
});

const handleSetOpeningBalance = Effect.fn('Finance.handleSetOpeningBalance')(function* setOpening(
  command: CommandOf<'SetOpeningBalance'>,
  context: FinanceTransitionContext,
): Effect.fn.Return<FinanceTransition, FinanceError> {
  return stateOnly({
    ...context.state,
    cashFlowOpening: {
      ...actorOf(context, command.actorLabel),
      confirmedAt: context.input.now,
      openingBalanceMinor: command.openingBalanceMinor,
      openingDate: command.openingDate,
    },
  });
});

export const transitionFinance = (
  state: FinanceState,
  request: FinanceCommand,
  scope: FinanceScope,
  validators: FinanceValidators,
  input: FinanceTransitionContext['input'],
): Effect.Effect<FinanceTransition, FinanceError> => {
  const context: FinanceTransitionContext = { input, scope, state, validators };
  switch (request._tag) {
    case 'CreateInvoiceDraft':
      return handleCreateInvoiceDraft(request, context);
    case 'CreateInvoiceFromOpportunity':
      return handleCreateInvoiceFromOpportunity(request, context);
    case 'UpdateInvoiceDraft':
      return handleUpdateInvoiceDraft(request, context);
    case 'ConfirmInvoice':
      return handleConfirmInvoice(request, context);
    case 'VoidInvoice':
      return handleVoidInvoice(request, context);
    case 'RequestAccountingSync':
    case 'RetryAccountingSync':
      return handleRetryAccountingSync(request, context);
    case 'ApplyAccountingObservation':
      return handleApplyAccountingObservation(request, context);
    case 'ApplyPaymentObservation':
      return handleApplyPaymentObservation(request, context);
    case 'RecordIncomingInvoice':
      return handleRecordIncomingInvoice(request, context);
    case 'AttachDocument':
      return handleAttachDocument(request, context);
    case 'SetInvoiceDetails':
      return handleSetInvoiceDetails(request, context);
    case 'RecordManualPayment':
      return handleRecordManualPayment(request, context);
    case 'RecordReminder':
      return handleRecordReminder(request, context);
    case 'CreateRecurringTemplate':
      return handleCreateRecurringTemplate(request, context);
    case 'SetRecurringTemplateActive':
      return handleSetRecurringTemplateActive(request, context);
    case 'GenerateRecurringInvoice':
      return handleGenerateRecurringInvoice(request, context);
    case 'UpdateAccountingSetup':
      return handleUpdateAccountingSetup(request, context);
    case 'CreateAccountingExport':
      return handleCreateAccountingExport(request, context);
    case 'ConfirmAccountingExport':
      return handleConfirmAccountingExport(request, context);
    case 'UpsertBudgetLine':
      return handleUpsertBudgetLine(request, context);
    case 'DeleteBudgetLine':
      return handleDeleteBudgetLine(request, context);
    case 'SetOpeningBalance':
      return handleSetOpeningBalance(request, context);
  }
};

export const projectFinanceRecords = (
  state: FinanceState,
  revision: number,
  request: RecordsRequest,
  businessDate: string = DEMO_BUSINESS_DATE,
): Omit<RecordsResponse, 'canWrite'> => {
  const invoices = state.invoices.filter(
    (record) =>
      (request.resourceId === undefined || record.ref.resourceId === request.resourceId) &&
      (request.propertyId === undefined || record.propertyRef?.resourceId === request.propertyId) &&
      // Party snapshots and commercial Counterparty refs are distinct identities.
      (request.partyId === undefined || record.partyId === request.partyId) &&
      (request.counterpartyRef === undefined ||
        (record.counterpartyRef.tenantId === request.counterpartyRef.tenantId &&
          record.counterpartyRef.moduleId === request.counterpartyRef.moduleId &&
          record.counterpartyRef.resourceType === request.counterpartyRef.resourceType &&
          record.counterpartyRef.resourceId === request.counterpartyRef.resourceId)) &&
      (request.opportunityId === undefined || record.opportunityId === request.opportunityId),
  );
  const selected = new Set(invoices.map((record) => record.ref.resourceId));
  const financialPlanEntries = state.financialPlanEntries.filter(
    (record) =>
      request.partyId === undefined &&
      request.counterpartyRef === undefined &&
      (request.propertyId === undefined || record.propertyRef.resourceId === request.propertyId) &&
      (request.resourceId === undefined || record.ref.resourceId === request.resourceId),
  );
  const accountingObservations = state.accountingObservations.filter((record) =>
    selected.has(record.invoiceRef.resourceId),
  );
  const paymentObservations = state.paymentObservations.filter((record) => selected.has(record.invoiceRef.resourceId));
  const confirmed = invoices.filter((record) => record.businessState === 'CONFIRMED');
  const actuals = confirmed.filter((record) => record.issueDate >= '2026-01-01' && record.issueDate < '2027-01-01');
  const outstanding = confirmed.filter((record) => record.paidMinor < record.totalMinor);
  const plans = financialPlanEntries.filter(
    (record) =>
      record.state === 'CONFIRMED' &&
      record.periodStart >= '2026-01-01' &&
      record.periodStart < '2027-01-01' &&
      record.periodEndExclusive > record.periodStart,
  );
  const sumActual = (direction: Invoice['direction']) =>
    actuals.filter((record) => record.direction === direction).reduce((sum, record) => sum + record.totalMinor, 0);
  const sumOutstanding = (direction: Invoice['direction']) =>
    outstanding
      .filter((record) => record.direction === direction)
      .reduce((sum, record) => sum + record.totalMinor - record.paidMinor, 0);
  const sumPlan = (kind: 'COST' | 'REVENUE') =>
    plans.filter((record) => record.kind === kind).reduce((sum, record) => sum + record.plannedMinor, 0);
  const costMinor = sumActual('INCOMING');
  const revenueMinor = sumActual('OUTGOING');
  const plannedCostMinor = sumPlan('COST');
  const plannedRevenueMinor = sumPlan('REVENUE');
  const payablesOutstandingMinor = sumOutstanding('INCOMING');
  const receivablesOutstandingMinor = sumOutstanding('OUTGOING');
  return {
    indicators: {
      costMinor,
      costVarianceMinor: costMinor - plannedCostMinor,
      draftCount: invoices.filter((record) => record.businessState === 'DRAFT').length,
      grossOutstandingMinor: payablesOutstandingMinor + receivablesOutstandingMinor,
      integrationWarnings: new Set(
        accountingObservations.flatMap((record) =>
          record.latest && record.status === 'FAILED' ? [record.correlation] : [],
        ),
      ).size,
      openIncomingInvoices: outstanding.filter((record) => record.direction === 'INCOMING').length,
      openInvoices: outstanding.length,
      openOutgoingInvoices: outstanding.filter((record) => record.direction === 'OUTGOING').length,
      overdueInvoices: outstanding.filter((record) => isInvoiceOverdue(record, businessDate)).length,
      payablesOutstandingMinor,
      plannedCostMinor,
      plannedRevenueMinor,
      receivablesOutstandingMinor,
      revenueMinor,
      revenueVarianceMinor: revenueMinor - plannedRevenueMinor,
    },
    businessDate,
    referenceDate: DEMO_BUSINESS_DATE,
    revision,
    state: {
      ...optionalStateParts(state, selected, request),
      accountingObservations,
      financialPlanEntries,
      invoices,
      paymentObservations,
    },
  };
};

/** Demo-v2 parts of the state. Invoice-scoped records follow the invoice filter; ledger-wide ones only unfiltered. */
const optionalStateParts = (state: FinanceState, selected: ReadonlySet<string>, request: RecordsRequest) => {
  const unfiltered =
    request.resourceId === undefined &&
    request.partyId === undefined &&
    request.counterpartyRef === undefined &&
    request.opportunityId === undefined &&
    request.propertyId === undefined;
  const byInvoice = <T extends { readonly invoiceResourceId?: string | undefined }>(
    records: readonly T[] | undefined,
  ) => records?.filter((record) => record.invoiceResourceId !== undefined && selected.has(record.invoiceResourceId));
  const parts = {
    accountingExports: unfiltered ? state.accountingExports : undefined,
    accountingSetup: state.accountingSetup,
    budgets: unfiltered ? state.budgets : undefined,
    cashFlowOpening: unfiltered ? state.cashFlowOpening : undefined,
    documents: byInvoice(state.documents),
    manualPayments: byInvoice(state.manualPayments),
    recurringTemplates: unfiltered ? state.recurringTemplates : undefined,
    reminders: byInvoice(state.reminders),
  };
  return Object.fromEntries(Object.entries(parts).filter(([, value]) => value !== undefined)) as Partial<
    Pick<
      FinanceState,
      | 'accountingExports'
      | 'accountingSetup'
      | 'budgets'
      | 'cashFlowOpening'
      | 'documents'
      | 'manualPayments'
      | 'recurringTemplates'
      | 'reminders'
    >
  >;
};
